import React,{useEffect,useState} from 'react';
import {View,Text,TextInput,Switch,Pressable,Modal,ScrollView} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import {parseRecordState,mutateRecords,recordLabel,relationLabel} from './mobile-data';
const key='loam-records';let writes=Promise.resolve();const listeners=new Set();
const load=async()=>parseRecordState(await AsyncStorage.getItem(key));
function commit(schemas,action){const result=writes.catch(()=>{}).then(async()=>{const changed=mutateRecords(await load(),schemas,action);if(!Object.keys(changed.errors).length){await AsyncStorage.setItem(key,JSON.stringify(changed.state));listeners.forEach(fn=>fn());}return changed;});writes=result;return result;}
export default function Records({project,collectionId,theme}){
 const schema=project.collections.find(c=>c.id===collectionId),[state,setState]=useState(null),[failure,setFailure]=useState(''),[notice,setNotice]=useState(''),[editing,setEditing]=useState(undefined),[values,setValues]=useState({}),[errors,setErrors]=useState({}),[query,setQuery]=useState(''),[trash,setTrash]=useState(false),[filter,setFilter]=useState(''),[choice,setChoice]=useState(null),[pending,setPending]=useState(false);
 useEffect(()=>{let alive=true;const refresh=()=>load().then(s=>{if(alive)setState(s);}).catch(e=>{if(alive)setFailure(e.message);});listeners.add(refresh);refresh();return()=>{alive=false;listeners.delete(refresh);};},[]);
 const text={color:theme.foreground,textAlign:project.direction==='rtl'?'right':'left'},box={borderWidth:1,borderColor:theme.border,borderRadius:12,padding:12,marginBottom:10},button={...box,minHeight:44,backgroundColor:theme.card};
 const btn=(label,onPress,primary=false)=><Pressable accessibilityRole="button" disabled={pending} style={[button,primary&&{backgroundColor:theme.primary}]} onPress={onPress}><Text style={[text,primary&&{color:theme['on-primary']}]}>{label}</Text></Pressable>;
 function open(row){setEditing(row||null);setValues({...row?.values});setErrors({});setFailure('');setNotice('');}
 async function act(action){setPending(true);setFailure('');try{const result=await commit(project.collections,{...action,collectionId});setErrors(result.errors);if(!Object.keys(result.errors).length){setState(result.state);setEditing(undefined);setNotice(action.type==='save'?'تم حفظ '+schema.singular:action.type==='delete'?'نُقل السجل إلى المحذوفات؛ يمكنك استعادته.':'تمت استعادة '+schema.singular);}}catch(e){setFailure(e.message);}finally{setPending(false);}}
 const display=(f,row)=>{const value=row.values[f.id];if(f.type==='boolean')return value?'نعم':'لا';if(f.type==='relation'){const related=project.collections.find(c=>c.id===f.collectionId),records=state.collections[f.collectionId]||[],record=records.find(r=>r.id===value);return record?relationLabel(related,record,records):'غير محدد';}return String(value??'');};
 if(!state)return <Text style={text}>{failure||'جارٍ تحميل البيانات…'}</Text>;
 const all=state.collections[collectionId]||[],filterField=schema.fields.find(f=>f.type==='select'),rows=all.filter(r=>!!r.deletedAt===trash&&(!filter||r.values[filterField?.id]===filter)&&schema.fields.some(f=>display(f,r).toLocaleLowerCase().includes(query.toLocaleLowerCase()))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
 return <View><Text accessibilityLiveRegion="polite" style={[text,failure&&{color:'#ac2737'}]}>{failure||notice}</Text>{editing!==undefined?<View>
  {btn('عودة إلى القائمة',()=>setEditing(undefined))}<Text style={[text,{fontSize:22,marginBottom:16}]}>{editing?'تعديل ':'إضافة '}{schema.singular}</Text>
  {schema.fields.map(f=><View key={f.id} style={{marginBottom:12}}><Text style={text}>{f.label}{f.required?' *':''}</Text>{f.type==='boolean'?<Switch accessibilityLabel={f.label} value={values[f.id]===true} onValueChange={v=>setValues(old=>({...old,[f.id]:v}))}/>:['select','relation'].includes(f.type)?btn(values[f.id]?display(f,{values}):'اختر…',()=>setChoice(f)):<TextInput accessibilityLabel={f.label} style={[box,text]} value={String(values[f.id]??'')} onChangeText={v=>setValues(old=>({...old,[f.id]:v}))} keyboardType={f.type==='number'?'decimal-pad':'default'} maxLength={2000} placeholder={f.type==='date'?'YYYY-MM-DD':''}/>}<Text style={[text,{color:'#ac2737'}]}>{errors[f.id]||''}</Text></View>)}
  {btn('حفظ '+schema.singular,()=>act({type:'save',id:editing?.id,expectedUpdatedAt:editing?.updatedAt,values}),true)}
 </View>:<View><Text style={[text,{fontSize:20,marginBottom:10}]}>{schema.title} · {all.filter(r=>!r.deletedAt).length}</Text>{btn('إضافة '+schema.singular,()=>open(null),true)}<TextInput accessibilityLabel={'ابحث في '+schema.title} placeholder={'ابحث في '+schema.title} value={query} onChangeText={setQuery} style={[box,text]}/>{filterField&&btn(filter||'كل '+filterField.label,()=>setChoice({...filterField,filter:true}))}{btn(trash?'عرض السجلات':'المحذوفات ('+all.filter(r=>r.deletedAt).length+')',()=>setTrash(!trash))}
  {!rows.length&&<Text style={text}>{query||filter?'لا توجد نتائج مطابقة':trash?'المحذوفات فارغة':'ابدأ بإضافة '+schema.singular+'؛ ستظهر سجلاتك هنا.'}</Text>}
  {rows.map(row=><View key={row.id} style={[box,{backgroundColor:theme.card}]}><Text style={[text,{fontSize:18,fontWeight:'600'}]}>{recordLabel(schema,row)}</Text>{schema.fields.filter(f=>f.id!==schema.titleField).slice(0,4).map(f=><Text key={f.id} style={text}>{f.label} · {display(f,row)}</Text>)}{trash?btn('استعادة '+schema.singular,()=>act({type:'restore',id:row.id,expectedUpdatedAt:row.updatedAt})):<View>{btn('تعديل '+schema.singular,()=>open(row))}{btn('حذف '+schema.singular,()=>act({type:'delete',id:row.id,expectedUpdatedAt:row.updatedAt}))}</View>}</View>)}
 </View>}<Modal visible={!!choice} transparent animationType="slide" onRequestClose={()=>setChoice(null)}><View style={{flex:1,backgroundColor:'#0008',justifyContent:'flex-end'}}><ScrollView style={{maxHeight:'70%',backgroundColor:theme.background,padding:20}}><Text style={text}>{choice?.label}</Text>{btn('إغلاق',()=>setChoice(null))}{choice&&[{id:'',label:'بدون اختيار'},...(choice.type==='select'?choice.options.map(v=>({id:v,label:v})):(state.collections[choice.collectionId]||[]).filter(r=>!r.deletedAt).map(r=>({id:r.id,label:relationLabel(project.collections.find(c=>c.id===choice.collectionId),r,state.collections[choice.collectionId]||[])})))].map(option=><View key={option.id}>{btn(option.label,()=>{choice.filter?setFilter(option.id):setValues(old=>({...old,[choice.id]:option.id}));setChoice(null);})}</View>)}</ScrollView></View></Modal></View>;
}
